instruction:
Refactor this code by applying the Single Responsibility Principle to the god class:

class UserAdmin:
    def __init__(self, uid):
        self.uid = uid
    def validate(self, data):
        return bool(data.get('email'))
    def save(self, data):
        db.execute('INSERT INTO users ...', data)
        return data
    def send_welcome(self, data):
        smtp.send(data['email'], 'Welcome', body)
    def audit(self, action):
        log.info('user %s %s', self.uid, action)

output:
class UserValidator:
    @staticmethod
    def validate(data):
        return bool(data.get('email'))

class UserRepository:
    def save(self, data):
        db.execute('INSERT INTO users ...', data)
        return data

class WelcomeMailer:
    def send(self, email):
        smtp.send(email, 'Welcome', body)

class AuditLog:
    def record(self, uid, action):
        log.info('user %s %s', uid, action)

# orchestration stays thin:
def create_user(data, repo, mailer, audit):
    if not UserValidator.validate(data):
        raise ValueError('invalid')
    repo.save(data)
    mailer.send(data['email'])
    audit.record(data['id'], 'created')

What changed: validation, persistence, mail and auditing each got their own class; changing SMTP no longer risks breaking SQL.

instruction:
Refactor this code by applying the Open/Closed Principle to the area calculation:

def area(shapes):
    total = 0
    for s in shapes:
        if s['type'] == 'circle':
            total += 3.14159 * s['r'] ** 2
        elif s['type'] == 'square':
            total += s['side'] ** 2
        elif s['type'] == 'rect':
            total += s['w'] * s['h']
    return total

output:
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

class Circle(Shape):
    def __init__(self, r): self.r = r
    def area(self): return 3.14159 * self.r ** 2

class Square(Shape):
    def __init__(self, side): self.side = side
    def area(self): return self.side ** 2

class Rectangle(Shape):
    def __init__(self, w, h): self.w, self.h = w, h
    def area(self): return self.w * self.h

def area(shapes):
    return sum(s.area() for s in shapes)

What changed: area() is open for extension (new Shape subclasses) but closed for modification; the central if/elif never changes again.

instruction:
Refactor this code by fixing the Liskov Substitution violation in the rectangle hierarchy:

class Rectangle:
    def __init__(self, w, h): self.w, self.h = w, h
    def set_width(self, w): self.w = w
    def set_height(self, h): self.h = h

class Square(Rectangle):
    def set_width(self, w):
        self.w = self.h = w
    def set_height(self, h):
        self.w = self.h = h

def resize(r, w, h):
    r.set_width(w)
    r.set_height(h)
    return r.w * r.h   # not w*h for a Square

output:
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...

class Rectangle(Shape):
    def __init__(self, w, h): self.w, self.h = w, h

class Square(Shape):
    def __init__(self, side): self.side = side

class Ellipse(Shape):
    def __init__(self, a, b): self.a, self.b = a, b

def resize(rect: Rectangle, w, h):
    rect.w, rect.h = w, h
    return rect.area()

What changed: Square no longer masquerades as Rectangle; both implement the Shape contract, so functions can rely on substituted instances.

