instruction:
Refactor this code by splitting this multi-purpose function per the Single Responsibility Principle:

def import_and_notify(path):
    rows = []
    with open(path) as f:
        for line in f:
            rows.append(json.loads(line))
    for r in rows:
        db.insert(r)
    smtp.send('ops@example.com', 'import done', f'{len(rows)} rows')
    logger.info('imported %s rows', len(rows))

output:
def load_rows(path):
    with open(path) as f:
        return [json.loads(line) for line in f]

def persist(rows):
    for r in rows:
        db.insert(r)

def notify_ops(count):
    smtp.send('ops@example.com', 'import done', f'{count} rows')

def import_and_notify(path):
    rows = load_rows(path)
    persist(rows)
    notify_ops(len(rows))
    logger.info('imported %s rows', len(rows))

What changed: reading, writing and emailing are separate steps; the orchestrator sequences them and each step can be tested or reused alone.

instruction:
Refactor this code by using a registry so payment types extend behavior instead of editing the switch:

def charge(kind, amount):
    if kind == 'card':
        return stripe.charge(amount)
    elif kind == 'paypal':
        return paypal.charge(amount)
    elif kind == 'invoice':
        return billing.later(amount)
    raise ValueError(kind)

output:
PAYMENTS = {}

def payment(kind):
    def register(cls):
        PAYMENTS[kind] = cls
        return cls
    return register

@payment('card')
class CardPayment:
    def charge(self, amount): return stripe.charge(amount)

@payment('paypal')
class PaypalPayment:
    def charge(self, amount): return paypal.charge(amount)

@payment('invoice')
class InvoicePayment:
    def charge(self, amount): return billing.later(amount)

def charge(kind, amount):
    try:
        processor = PAYMENTS[kind]()
    except KeyError:
        raise ValueError(kind) from None
    return processor.charge(amount)

What changed: adding a payment method is a new registered class; charge() and every existing branch remain untouched (open/closed via a registry).

