Refactor this code by separating validation from transformation per SRP:

def normalize_user(payload):
    payload['email'] = payload['email'].strip().lower()
    payload['age'] = int(payload['age'])
    if '@' not in payload['email']:
        raise ValueError('bad email')
    if payload['age'] < 0:
        raise ValueError('bad age')
    payload['name'] = payload['name'].title()
    return payload

output:
def validate_user(payload):
    if '@' not in payload['email']:
        raise ValueError('bad email')
    if int(payload['age']) < 0:
        raise ValueError('bad age')
    return payload

def normalize_user(payload):
    payload['email'] = payload['email'].strip().lower()
    payload['age'] = int(payload['age'])
    payload['name'] = payload['name'].title()
    return payload

def prepare_user(payload):
    return normalize_user(validate_user(payload))

What changed: deciding correctness (validate) and changing shape (normalize) are separate; either can be reused or reordered without editing the other.

instruction:
Refactor this code by fixing the subclass that breaks its parent's contract:

class Store:
    def put(self, key, value): self._d[key] = value
    def get(self, key): return self._d.get(key)
    def keys(self): return list(self._d)

class ReadOnlyStore(Store):
    def put(self, key, value):
        raise TypeError('read-only')
    def keys(self):
        raise TypeError('nope')

output:
from abc import ABC, abstractmethod

class Readable(ABC):
    @abstractmethod
    def get(self, key): ...
    @abstractmethod
    def keys(self): ...

class Writable(Readable):
    @abstractmethod
    def put(self, key, value): ...

class Store(Writable):
    def __init__(self): self._d = {}
    def put(self, key, value): self._d[key] = value
    def get(self, key): return self._d.get(key)
    def keys(self): return list(self._d)

class ReadOnlyStore(Readable):
    def __init__(self, source): self._source = source
    def get(self, key): return self._source.get(key)
    def keys(self): return self._source.keys()

What changed: ReadOnlyStore no longer inherits methods it refuses to honor; code wanting write access types against Writable and cannot receive a read-only.

instruction:
Refactor this code by extracting an interface for the rendering client used by three modules:

def html_page(data):
    r = requests.post('https://render.internal/html', json=data)
    return r.text

def pdf_page(data):
    r = requests.post('https://render.internal/pdf', json=data)
    return r.content

def png_page(data):
    r = requests.post('https://render.internal/png', json=data)
    return r.content

output:
from abc import ABC, abstractmethod

class Renderer(ABC):
    @abstractmethod
    def render(self, data): ...

class RemoteRenderer(Renderer):
    def __init__(self, endpoint, session=None):
        self.endpoint = endpoint
        self.session = session or requests
    def render(self, data):
        r = self.session.post(self.endpoint, json=data, timeout=10)
        r.raise_for_status()
        return r.text if 'html' in self.endpoint else r.content

HTML = RemoteRenderer('https://render.internal/html')
PDF = RemoteRenderer('https://render.internal/pdf')
PNG = RemoteRenderer('https://render.internal/png')

What changed: three modules that all knew the transport now share one Renderer abstraction; a local renderer can be substituted for tests.

instruction:
Refactor this code by splitting the repository and serialization responsibilities (SRP):

class UserService:
    def __init__(self, conn): self.conn = conn
    def all_json(self):
        rows = self.conn.execute('SELECT * FROM users').fetchall()
        return json.dumps([dict(r) for r in rows])
    def all_csv(self):
        rows = self.conn.execute('SELECT * FROM users').fetchall()
        out = 'id,name\n'
        for r in rows:
            out += f"{r['id']},{r['name']}\n"
        return out

output:
class UserRepository:
    def __init__(self, conn): self.conn = conn
    def all(self):
        return [dict(r) for r in self.conn.execute('SELECT * FROM users').fetchall()]

class UserSerializer:
    @staticmethod
    def to_json(users): return json.dumps(users)
    @staticmethod
    def to_csv(users):
        lines = ['id,name'] + [f"{u['id']},{u['name']}" for u in users]
        return '\n'.join(lines) + '\n'

# use: UserSerializer.to_csv(UserRepository(conn).all())

What changed: SQL lives in the repository, output formats live in the serializer; adding XML touches only the serializer.

instruction:
Refactor this code by making the high-level module depend on an abstraction (DIP):

class BudgetReport:
    def __init__(self):
        self.client = StripeClient(api_key=os.environ['STRIPE_KEY'])
    def monthly(self, month):
        charges = self.client.charges(month)
        return sum(c.amount for c in charges)

output:
from abc import ABC, abstractmethod

class ChargeSource(ABC):
    @abstractmethod
    def charges(self, month): ...

class BudgetReport:
    def __init__(self, source: ChargeSource):
        self.source = source
    def monthly(self, month):
        return sum(c.amount for c in self.source.charges(month))

class StripeSource(ChargeSource):
    def __init__(self, client): self.client = client
    def charges(self, month): return self.client.charges(month)

# BudgetReport(StripeSource(StripeClient(key)))  at the composition root

What changed: BudgetReport no longer constructs or knows Stripe; it consumes a ChargeSource, so tests pass a stub with canned charges.

instruction:
Refactor this code by replacing conditional discount rules with rule objects (OCP):

def discount(user, amount):
    if user.get('vip'):
        amount *= 0.9
    if amount > 500:
        amount *= 0.95
    if user.get('coupon') == 'WELCOME':
        amount -= 10
    return max(0, amount)

output:
from dataclasses import dataclass

class Rule:
    def applies(self, user, amount): ...
    def apply(self, user, amount): ...

@dataclass
class VipDiscount(Rule):
    def applies(self, user, amount): return user.get('vip', False)
    def apply(self, user, amount): return amount * 0.9

@dataclass
class BulkDiscount(Rule):
    threshold: float = 500
    def applies(self, user, amount): return amount > self.threshold
    def apply(self, user, amount): return amount * 0.95

@dataclass
class WelcomeCoupon(Rule):
    code: str = 'WELCOME'
    def applies(self, user, amount): return user.get('coupon') == self.code
    def apply(self, user, amount): return amount - 10

def discount(user, amount, rules=(VipDiscount(), BulkDiscount(), WelcomeCoupon())):
    for rule in rules:
        if rule.applies(user, amount):
            amount = rule.apply(user, amount)
    return max(0, amount)

What changed: each discount is a Rule; new promotions are new objects (or config), and discount() never grows another elif.

from abc import ABC, abstractmethod

class Mailer(ABC):
