Refactor this code by replacing the concrete dependency chain with a service interface (DIP):

class NotificationSender:
    def __init__(self):
        self.twilio = TwilioClient(account, token)
        self.redis = Redis(host='cache')
    def send(self, to, msg):
        self.redis.set(f'sent:{to}', msg)
        self.twilio.messages.create(to=to, from_=FROM, body=msg)

output:
from abc import ABC, abstractmethod

class MessageGateway(ABC):
    @abstractmethod
    def send(self, to, msg): ...

class SentLog(ABC):
    @abstractmethod
    def record(self, to, msg): ...

class NotificationSender:
    def __init__(self, gateway: MessageGateway, sent_log: SentLog):
        self.gateway = gateway
        self.sent_log = sent_log
    def send(self, to, msg):
        self.sent_log.record(to, msg)
        self.gateway.send(to, msg)

What changed: two concrete clients became two ports; NotificationSender's orchestration is testable without Twilio or Redis running.

