Refactor this code by composing small single-purpose classes instead of one multi-role class (SRP):

class DataPipeline:
    def fetch(self): return requests.get(URL).json()
    def clean(self, rows): return [r for r in rows if r.get('ok')]
    def store(self, rows):
        with open('out.json', 'w') as f: json.dump(rows, f)
    def alert(self, n): pagerduty.trigger(f'{n} rows')
    def run(self):
        rows = self.clean(self.fetch())
        self.store(rows)
        self.alert(len(rows))

output:
class Fetcher:
    def fetch(self): return requests.get(URL).json()

class Cleaner:
    def clean(self, rows): return [r for r in rows if r.get('ok')]

class Store:
    def store(self, rows):
        with open('out.json', 'w') as f: json.dump(rows, f)

class Alerter:
    def alert(self, n): pagerduty.trigger(f'{n} rows')

class DataPipeline:
    def __init__(self, fetcher, cleaner, store, alerter):
        self.fetcher, self.cleaner, self.store, self.alerter = fetcher, cleaner, store, alerter
    def run(self):
        rows = self.cleaner.clean(self.fetcher.fetch())
        self.store.store(rows)
        self.alerter.alert(len(rows))

What changed: four responsibilities became four collaborators injected into an orchestrator; each piece changes and tests independently.
